impl store::ArtifactSqliteSnapshot for LayoutSnapshot{
 const SQLITE_SCHEMA:&'static str=SCHEMA;
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{project(self,control)}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{reconstruct(database,control)}
 fn retire_sqlite_snapshot(self){crate::standards::v1::subsets::any::schema::snapshot::retire(self);}
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{
  control.check_rows(2)?;
  store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record,native|{let owner=semio_framework_value::DecodedValue::new(Self::__dsl_from_record_controlled(record,native)?,retire);if let Some(dictionary)=&owner.get().data_fields{dictionary.validate_controlled(native)?;}Ok(owner.take())},control)
 }
 fn encode_sqlite_snapshot_native(&self,encoding:store::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{
  control.check_rows(2)?;
  store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|{if let Some(dictionary)=&self.data_fields{dictionary.validate_controlled(native)?;}self.__dsl_to_record_controlled(native)},control)
 }
 fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{
  control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;
  if dialect.artifact_kind!="s.layout.layout"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(ValueError::new(ValueRefusalKind::UnsupportedOwner,"Layout does not own the declared semantic subset")))}
  validate_sqlite_database_schema(database,SCHEMA,control.limits()).map_err(store::io_schema::IoError::from_value_error)?;
  Ok(store::io_schema::IoOutcome::clean(()))
 }
}

